<script>
(function(){var modal=document.getElementById('lc-consent-modal'),body=document.getElementById('lc-consent-body');function close(){modal.classList.remove('is-open');body.innerHTML='';}document.addEventListener('click',function(e){var button=e.target.closest('.js-lc-consent');if(!button)return;modal.classList.add('is-open');body.innerHTML='<div class="text-center p-4"><i class="fas fa-circle-notch fa-spin mr-1"></i> Cargando documentos…</div>';fetch(button.getAttribute('data-url'),{headers:{'X-Requested-With':'XMLHttpRequest'}}).then(function(r){if(!r.ok)throw new Error('request');return r.text();}).then(function(html){body.innerHTML=html;}).catch(function(){body.innerHTML='<div class="alert alert-danger">No se pudieron cargar los documentos de esta orden.</div>';});});modal.querySelector('.lc-modal__close').addEventListener('click',close);modal.addEventListener('click',function(e){if(e.target===modal)close();});document.addEventListener('keydown',function(e){if(e.key==='Escape')close();});})();
</script>
